-- Internal management data only. No updates to DingTalk source tables.
create table if not exists attendance_offset_events(id text primary key,person_id text not null,work_date text not null,kind text not null,planned text not null,evidence_json text not null,evidence_hash text not null,revision integer not null,active integer not null,updated_at text not null);
create index if not exists attendance_offset_event_person on attendance_offset_events(person_id,work_date);
create table if not exists attendance_shift_responsibilities(id text primary key,person_id text not null,work_date text not null,team text not null,leader_person_id text not null,assignee_user_id text not null,evidence text not null,confirmed_by text not null,confirmed_at text not null,version integer not null,unique(person_id,work_date));
create table if not exists action_tasks(id text primary key,source_module text not null,source_type text not null,source_id text not null,action_type text not null,assignee_user_id text not null,title text not null,status text not null,target_json text not null,created_at text not null,updated_at text not null,unique(source_module,source_type,source_id,action_type,assignee_user_id));
create index if not exists action_task_assignee on action_tasks(assignee_user_id,status,created_at,id);
create table if not exists attendance_offset_rules(id text primary key,source_month text not null unique,threshold_seconds integer not null check(threshold_seconds>0),unit_count integer not null check(unit_count>0),monthly_cap integer not null check(monthly_cap>=0),people_json text not null,created_by text not null,created_at text not null);
create table if not exists attendance_offset_accounts(person_id text not null,usage_month text not null,source_month text not null,rule_id text not null,source_seconds integer not null,source_version text not null,status text not null,granted integer not null check(granted>=0),frozen integer not null default 0 check(frozen>=0),used integer not null default 0 check(used>=0),version integer not null default 1,primary key(person_id,usage_month),check(granted>=frozen+used));
create table if not exists attendance_offset_ledger(id text primary key,person_id text not null,usage_month text not null,kind text not null,amount integer not null,reference_id text not null,created_at text not null,unique(kind,reference_id));
create index if not exists attendance_offset_ledger_person on attendance_offset_ledger(person_id,usage_month,created_at);
create table if not exists attendance_offset_requests(id text primary key,person_id text not null,usage_month text not null,assignee_user_id text not null,responsibility_json text not null,note text not null,status text not null,version integer not null default 1,created_at text not null,updated_at text not null);
create table if not exists attendance_offset_items(id text primary key,request_id text not null,event_id text not null,evidence_hash text not null,event_revision integer not null,decision text not null,effective integer not null default 0,reason text,decided_by text,decided_at text);
create index if not exists attendance_offset_items_request on attendance_offset_items(request_id);
create table if not exists attendance_offset_claims(event_id text primary key,item_id text not null unique);
create table if not exists attendance_offset_operations(actor_id text not null,action text not null,operation_key text not null,request_hash text not null,result_json text not null,primary key(actor_id,action,operation_key));
create table if not exists attendance_offset_audit(id text primary key,actor_id text not null,action text not null,reference_id text not null,detail_json text not null,created_at text not null);
create table if not exists attendance_offset_state(id text primary key,version integer not null);
create table if not exists attendance_offset_event_links(old_id text not null,new_id text not null,reason text not null,created_at text not null,primary key(old_id,new_id));
create table if not exists attendance_offset_dirty(person_id text not null,work_date text not null,generation integer not null,processed_generation integer not null default 0,primary key(person_id,work_date));
create table if not exists attendance_offset_event_history(event_id text not null,revision integer not null,evidence_json text not null,evidence_hash text not null,active integer not null,recorded_at text not null,primary key(event_id,revision));
create index if not exists attendance_offset_request_person on attendance_offset_requests(person_id,created_at);
create index if not exists attendance_offset_request_pending on attendance_offset_requests(status,assignee_user_id);
create table if not exists attendance_offset_assessments(person_id text not null,source_month text not null,status text not null,coverage_json text not null,source_seconds integer not null,source_version text not null,checked_at text not null,primary key(person_id,source_month));
